    var CTYPES=['Incline treadmill walk','Treadmill run','Outdoor walk','Outdoor run','Bike','Spin bike / spin class','Cross trainer','Rower','Stair climber','SkiErg','Swimming','Skipping','HIIT class','Sports / football / netball','Hiking','Other'];
