      m.innerHTML='<div class="lb-sheet-c"><b>Set '+(k+1)+'</b><small>What kind of set was this?</small>'+[['','Normal set']].concat(Object.keys(ST).map(function(t){return [t,ST[t][0]+' · '+ST[t][1]]})).map(function(o){return '<button type="button" data-t="'+o[0]+'" class="'+((s.t||'')===o[0]?'on':'')+'">'+o[1]+'</button>'}).join('')+'<button type="button" data-t="del" class="red">🗑 Delete this set</button><button type="button" data-t="x0" class="g">Cancel</button></div>';
